// spec: specs/placement-reading-adaptive.md (1.1–1.4) · кейсы PA-01, PA-02, PA-03, PA-04, PA-05 · запасной путь (Supabase REST, второе окно parent-3)
// seed: tests/seed.parent.spec.ts
// Голос не автоматизируется (в headless микрофона нет): каждый отрывок — «קראתי!» → «לנסות שוב» → самооценка.
// PA-06 (уверенный результат по чтению вслух) — только вручную голосом; PA-07 (C3 без номера уровня) уже покрыт placement-reading 1.2.
// Каждый тест создаёт 1 ребёнка QA-AUTO-… — удаляет пользователь (нужен пароль родителя), имя и id — в annotations «cleanup».
// Не прогонять при записи — запуск только по /qa-regress.
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  childUrl,
  handoverToIntro,
  passReadingToResults,
  qaChildName,
  readingScreens,
  trackSupabaseRest,
  type SelfRating,
} from '../placement-reading/reading.helpers';
import { BIDI, birthYearForAge, createChildWithLevels, vis } from '../writing-submit/writing.helpers';
import { RATING_STEP, clampLevel, placementPassageLevels } from './adaptive.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

interface AdaptiveCase {
  title: string;
  age: number;
  estimate?: number;
  rating: SelfRating;
  first: number;
}

// Старт: по возрасту (6→1 … 12+→7; 7→2, 10→5, 13→7 — проверено 02.11), при оценке родителя — от неё.
const CASES: AdaptiveCase[] = [
  { title: 'Старт по возрасту: 7 лет → отрывок 2; «קל» → +2', age: 7, rating: 'קל', first: 2 },
  { title: 'Старт по возрасту: 13 лет → отрывок 7; «קשה» → −2', age: 13, rating: 'קשה', first: 7 },
  { title: 'Старт от оценки родителя: 10 лет и «רמת קריאה משוערת» 8 → отрывок 8; «בסדר» → +1', age: 10, estimate: 8, rating: 'בסדר', first: 8 },
];

test.describe('Адаптивный стартовый тест чтения (autotest-writer)', () => {
  for (const c of CASES) {
    test(`${c.title}; не больше 5 отрывков, уровни 1–10 @desktop @data #976cbc`, async ({ asUser }, testInfo) => {
      test.setTimeout(5 * 60_000);
      const kid = await asUser('parent');
      const name = qaChildName();
      const childId = await createChildWithLevels(kid, name, { birthYear: birthYearForAge(c.age), readingEstimate: c.estimate });
      annotateCleanup(testInfo, name, childId);

      const rest = trackSupabaseRest(kid);
      await handoverToIntro(kid, childId, name);
      await readingScreens(kid).start.click();
      await passReadingToResults(kid, c.rating);

      const { levels } = await placementPassageLevels(kid, rest, childId);
      // PA-01 / PA-02: первый отрывок по возрасту или от оценки родителя (комментарий программиста 01.11)
      expect(levels[0], `уровни отрывков: ${levels.join('→')}`).toBe(c.first);
      // PA-04 / Т6: не больше 5 отрывков, диапазон 1–10
      expect(levels.length, `уровни отрывков: ${levels.join('→')}`).toBeLessThanOrEqual(5);
      expect(levels.length, 'тест не адаптировался: всего один отрывок').toBeGreaterThanOrEqual(2);
      for (const l of levels) {
        expect(l).toBeGreaterThanOrEqual(1);
        expect(l).toBeLessThanOrEqual(10);
      }
      // PA-03 / F-08 «המבחן מתאים את הקטע הבא לתוצאות»: каждый следующий = предыдущий + шаг ответа (в пределах 1–10)
      for (let i = 1; i < levels.length; i++) {
        expect(levels[i], `переход ${i}: ${levels.join('→')}`).toBe(clampLevel(levels[i - 1] + RATING_STEP[c.rating as keyof typeof RATING_STEP]));
      }
    });
  }

  test('«לא בטוח» в каждом отрывке: 10 лет → 5, шаг −1, ≤5 отрывков, затем C3; у родителя «עדיין לא ודאי · משוער N / 10», uncertain:true @desktop @data #976cbc', async ({ asUser }, testInfo) => {
    test.setTimeout(5 * 60_000);
    const kid = await asUser('parent');
    const name = qaChildName();
    const childId = await createChildWithLevels(kid, name, { birthYear: birthYearForAge(10) });
    annotateCleanup(testInfo, name, childId);

    const rest = trackSupabaseRest(kid);
    await handoverToIntro(kid, childId, name);
    await readingScreens(kid).start.click();
    await passReadingToResults(kid, 'לא בטוח/ה');
    // PA-04: после не более 5 отрывков — C3
    await kid.waitForURL(childUrl(childId, 'assessment/results'));
    await expect(readingScreens(kid).resultsTitle).toBeVisible();

    const { levels } = await placementPassageLevels(kid, rest, childId);
    expect(levels[0], `уровни отрывков: ${levels.join('→')}`).toBe(5);
    expect(levels.length).toBeLessThanOrEqual(5);
    for (let i = 1; i < levels.length; i++) expect(levels[i], `переход ${i}: ${levels.join('→')}`).toBe(clampLevel(levels[i - 1] - 1));

    // PA-05 / D-06: только самооценка → uncertain:true (skill_levels чтения). TODO verify: имена колонок domain / uncertain.
    const { base, headers } = await rest.auth();
    const resp = await kid.request.get(`${base}/rest/v1/skill_levels?child_id=eq.${childId}&select=*`, { headers });
    expect(resp.status(), `skill_levels: HTTP ${resp.status()}`).toBe(200);
    const reading = ((await resp.json()) as Record<string, unknown>[]).filter((r) => r.domain === 'reading');
    expect(reading.length, 'нет записи skill_levels по чтению').toBeGreaterThanOrEqual(1);
    expect(reading.at(-1)!.uncertain, JSON.stringify(reading.at(-1))).toBe(true);

    // У родителя (окно parent-3): «עדיין לא ודאי · משוער N / 10» (тикет «הערכה עצמית בלבד → «עדיין לא ודאי»»)
    const parent = await asUser('parent-3');
    await parent.goto(`/children/${childId}`);
    await expect(vis(parent.getByText('רמות נוכחיות (להורה בלבד)'))).toBeVisible();
    await expect(vis(parent.getByText(/קריאה:/))).toHaveText(new RegExp(`קריאה: עדיין לא ודאי · משוער ${BIDI}\\d+ / 10${BIDI}`));
  });
});
